-- #456: git 원본 release request 발행의 배포 채널 관측(관측 전용, h2 테스트 방언).
CREATE TABLE datapack_release_channel_observations (channel VARCHAR(32) NOT NULL PRIMARY KEY, release_sequence BIGINT NOT NULL, manifest_sha256 VARCHAR(64) NOT NULL, release_request_id VARCHAR(255) NOT NULL, binding_signature_sha256 VARCHAR(64) NOT NULL, delivery_idempotency_key VARCHAR(400) NOT NULL, workflow_run_url VARCHAR(1000), observed_at TIMESTAMP NOT NULL, CONSTRAINT chk_datapack_release_channel_observations_channel CHECK (channel IN ('dev', 'staging', 'production')), CONSTRAINT chk_datapack_release_channel_observations_sequence CHECK (release_sequence > 0), CONSTRAINT chk_datapack_release_channel_observations_hashes CHECK (CHAR_LENGTH(manifest_sha256) = 64 AND CHAR_LENGTH(binding_signature_sha256) = 64));
